			input: "\t mixed\ttabs\nand\nspaces ",
			want:  map[string]int{"mixed": 1, "tabs": 1, "and": 1, "spaces": 1},
		},
		{
			name:  "hyphenated words kept intact",
			input: "well-known well known",
			want:  map[string]int{"well-known": 1, "well": 1, "known": 1},
		},
	}

